import XCTest
@testable import SecutgCore

/// PLAN.md 3.48.6: `vectors-l1.json`, generated by the Web client — the interop oracle for `L1:` encode/parse
/// and relay-content encryption across all four platforms. Copied byte-identically from
/// `secuTG/src/secutg/relay/core/vectors-l1.json`; do not hand-edit this JSON file.
final class RelayL1VectorTests: XCTestCase {
    private func vectors() -> [String: Any] {
        return Vectors.load("vectors-l1")
    }

    func testEncodeVectors() {
        guard let cases = vectors()["encode"] as? [[String: Any]] else { XCTFail("missing encode vectors"); return }
        for entry in cases {
            let name = entry["name"] as? String ?? "?"
            guard let fields = entry["fields"] as? [String: Any], let wire = entry["wire"] as? String else {
                XCTFail("\(name): malformed vector"); continue
            }
            guard let ref = reference(from: fields) else { XCTFail("\(name): could not build reference"); continue }
            XCTAssertEqual(RelayL1.encode(ref), wire, name)
        }
    }

    func testParseValidVectors() {
        guard let cases = vectors()["parseValid"] as? [[String: Any]] else { XCTFail("missing parseValid vectors"); return }
        for entry in cases {
            let name = entry["name"] as? String ?? "?"
            guard let wire = entry["wire"] as? String, let fields = entry["fields"] as? [String: Any],
                  let expected = reference(from: fields) else {
                XCTFail("\(name): malformed vector"); continue
            }
            switch RelayL1.parse(wire) {
            case .success(let parsed): XCTAssertEqual(parsed, expected, name)
            case .failure(let error): XCTFail("\(name): unexpected failure \(error)")
            }
        }
    }

    func testParseInvalidVectors() {
        guard let cases = vectors()["parseInvalid"] as? [[String: Any]] else { XCTFail("missing parseInvalid vectors"); return }
        for entry in cases {
            let name = entry["name"] as? String ?? "?"
            guard let wire = entry["wire"] as? String, let reason = entry["reason"] as? String else {
                XCTFail("\(name): malformed vector"); continue
            }
            switch RelayL1.parse(wire) {
            case .success: XCTFail("\(name): expected failure reason \(reason), got success")
            case .failure(let error): XCTAssertEqual(error.reasonCode, reason, name)
            }
        }
    }

    func testEncryptVectors() {
        guard let cases = vectors()["encrypt"] as? [[String: Any]] else { XCTFail("missing encrypt vectors"); return }
        for entry in cases {
            let name = entry["name"] as? String ?? "?"
            guard let keyB64 = entry["keyB64"] as? String, let nonceB64 = entry["nonceB64"] as? String,
                  let plaintext = entry["plaintextUtf8"] as? String, let blobB64 = entry["blobB64"] as? String,
                  let key = Base64Url.decode(keyB64), let nonce = Base64Url.decode(nonceB64),
                  let expectedBlob = Base64Url.decode(blobB64) else {
                XCTFail("\(name): malformed vector"); continue
            }
            let plaintextData = Data(plaintext.utf8)
            guard let blob = try? RelayCrypto.seal(plaintextData, key: key, nonce: nonce) else {
                XCTFail("\(name): seal failed"); continue
            }
            XCTAssertEqual([UInt8](blob), expectedBlob, name)
            XCTAssertEqual(RelayCrypto.open(blob, key: key), plaintextData, "\(name) (round trip)")
        }
    }

    // MARK: - Helpers

    private func reference(from fields: [String: Any]) -> RelayL1Reference? {
        guard let u = fields["u"] as? String, let id = fields["id"] as? String,
              let tRaw = fields["t"] as? String, let t = RelayContentType(rawValue: tRaw),
              let m = fields["m"] as? String, let n = (fields["n"] as? NSNumber)?.intValue,
              let r = (fields["r"] as? NSNumber)?.intValue, let e = (fields["e"] as? NSNumber)?.int64Value else {
            return nil
        }
        let k = fields["k"] as? String
        return RelayL1Reference(relayURL: u, id: id, contentType: t, mime: m, sizeBytes: n, maxReads: r, expiresAt: e, contentKey: k)
    }
}
